import pathlib,base64,json
root=pathlib.Path('/dataset/shaoshitong/search-r1-rl/bapo-e1-instruct-300-20261004')
files={'tools/resource_watch.py': '', 'tools/native-state-fixture.py': '', 'tools/hardware.sh': '', 'tools/ray_cli_compat.py': '', 'tools/bapo-retrieval-parity.py': '', 'tools/flash_preflight.py': '', 'tools/stage.sh': '', 'tools/stage-gpu-inner.sh': '', 'tools/native-actor-fixture.py': '', 'tools/verify_launch.py': '', 'tools/formal300.sbatch': '', 'tools/submit.sh': '', 'tools/owned_processes.py': '', 'tools/hardware.sbatch': '', 'tools/verify_shared_inputs.py': '', 'tools/numerics-gpu-fixture.py': '', 'tools/monitor.sh': '', 'tools/verify_hardware_receipt.py': '', 'tools/submission-worker-intent.py': '', 'tools/cpu-tests.py': '', 'logs/launch-approval.json': '', 'logs/tools-manifest.json': '', 'logs/INDEPENDENT-LAUNCH-TOOLS-REVIEW.md': ''}
assert root.is_dir() and not root.is_symlink()
assert not list((root/'runs').iterdir()),'Run exists: no mutation'
for name,payload in files.items():
 p=root/name;assert '..' not in pathlib.PurePosixPath(name).parts and not p.is_symlink()
 data=base64.b64decode(payload)
 if p.exists():assert p.read_bytes()==data,'Different existing fixed file '+str(p)
 else:
  with p.open('xb')as f:f.write(data)
 if p.suffix in ('.sh','.sbatch'):p.chmod(0o755)
print(json.dumps({'status':'APPROVED_TOOLS_DEPLOYED_NOT_HARDWARE','files':len(files),'root':str(root)}))
